changeSet.sql:
-- Most-common reporting query: per-country, per-decision, last N days
CREATE INDEX TFPM_ADDR_ENRICH.IX_COMP_COUNTRY_DECISION
    ON TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING
    (COUNTRY_HINT, DECISION, CREATED_AT) LOCAL;

-- Find pending dispatches (compliance system was unreachable)
CREATE INDEX TFPM_ADDR_ENRICH.IX_COMP_PENDING
    ON TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING
    (STATUS, CREATED_AT) LOCAL;

-- Drill-down by result id and by compliance request id
CREATE INDEX TFPM_ADDR_ENRICH.IX_COMP_RESULT
    ON TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING (RESULT_ID) LOCAL;

CREATE INDEX TFPM_ADDR_ENRICH.IX_COMP_REQUEST
    ON TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING (COMPLIANCE_REQUEST_ID) LOCAL;

rollback.sql:
DROP INDEX TFPM_ADDR_ENRICH.IX_COMP_REQUEST;
DROP INDEX TFPM_ADDR_ENRICH.IX_COMP_RESULT;
DROP INDEX TFPM_ADDR_ENRICH.IX_COMP_PENDING;
DROP INDEX TFPM_ADDR_ENRICH.IX_COMP_COUNTRY_DECISION;

changeSet.sql:
COMMENT ON TABLE TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING IS
    'Audit trail for compliance routing decisions. One row per cascade result, including BYPASS decisions. See docs/COMPLIANCE_INTEGRATION.md.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING.DECISION IS
    'BYPASS = passed straight through. ROUTE = sent to compliance for review. BLOCK = hard-blocked, no compliance review needed.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.COMPLIANCE_ROUTING.STATUS IS
    'PENDING = decision made, not yet dispatched (only for ROUTE). DISPATCHED = sent to compliance, awaiting verdict. RESOLVED = compliance verdict received. FAILED = dispatch failed permanently.';
